import 'package:forui/forui.dart';
import 'package:material_ui/material_ui.dart';

part 'colors.dart';
part 'typography.dart';
part 'style.dart';
part 'icons.dart';

/// Generated by Forui CLI from preset "ccbbbc" (Zinc · Blue · Inter · Lucide ·
/// medium radius), then adjusted for a native macOS feel: desktop density,
/// system fonts and the macOS accent blue.
///
/// Regenerate using "dart run forui theme create --preset ccbbbc".
///
/// See:
/// * https://forui.dev/docs/guides/customizing-themes for customizing themes.
/// * https://forui.dev/docs/guides/customizing-widget-styles for customizing individual widget styles.
FThemeData get lightTheme => buildTheme(Brightness.light);

FThemeData get darkTheme => buildTheme(Brightness.dark);

/// Builds the app theme for [brightness]. [highContrast] follows the macOS
/// "Increase contrast" setting with stronger borders and secondary text.
FThemeData buildTheme(Brightness brightness, {bool highContrast = false}) {
  const touch = false;

  var colors = brightness == Brightness.dark ? darkColors : lightColors;
  if (highContrast) {
    colors = _highContrast(colors);
  }

  final typography = _typography(colors: colors, touch: touch);

  final icons = _icons();

  final style = _style(colors: colors, typography: typography, touch: touch);

  return FThemeData(
    colors: colors,
    typography: typography,
    icons: icons,
    style: style,
    touch: touch,
    // macOS sheets dim the window behind them; they do not blur it.
    dialogRouteStyle: FDialogRouteStyle(
      barrierFilter: (context, animation) => ColorFilter.mode(
        Color.lerp(const Color(0x00000000), colors.barrier, animation)!,
        BlendMode.srcOver,
      ),
    ),
  );
}
